        url: "\u0410\u0434\u0440\u0435\u0441",
        urldate: "\u0414\u0430\u0442\u0430 \u043D\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0430",
        venue: "\u041C\u044F\u0441\u0442\u043E \u043D\u0430 \u043F\u0440\u043E\u0432\u0435\u0436\u0434\u0430\u043D\u0435 \u043D\u0430 \u043A\u043E\u043D\u0444\u0435\u0440\u0435\u043D\u0446\u0438\u044F\u0442\u0430",
