// src/overview/index.ts
var BibliographyOverview = class {
  app;
  container;
  bibPlugins;
  lastSort;
  dom;
  overviewTable;
  table;
  dtBulk;
  menu;
  plugins;
  _boundHandleActivation;
  constructor({ app: app2, container }, bibPlugins = plugins) {
    this.app = app2;
    this.container = container;
    this.bibPlugins = bibPlugins;
    this.lastSort = { column: 0, dir: "asc" };
  }
  /** Bind the init function to doc loading.
   * @function bind
   */
  init() {
    return whenReady().then(() => {
      this.render();
      this.menu = new OverviewMenuView(
        this,
        menuModel
      );
      this.menu.init();
      this.setBibCategoryList(this.app.bibDB.cats);
      this.initTable(Object.keys(this.app.bibDB.db));
      window.scrollTo(0, 0);
      this.activatePlugins();
      this.bindEvents();
    });
  }
  render() {
    this.dom = this.container;
    this.dom.innerHTML = bibliographyOverviewTemplate();
    ensureCSS([
      staticUrl("css/bibliography/bibliography.css"),
      staticUrl("css/prosemirror.css"),
      staticUrl("css/fwtoolkit/inline_tools.css")
    ]);
    setDocTitle(gettext("Bibliography Manager"), this.app);
  }
  onResize() {
    if (!this.table) {
      return;
    }
    this.initTable(Object.keys(this.app.bibDB.db));
  }
  /* Initialize the overview table */
  initTable(ids) {
    if (this.overviewTable) {
      this.overviewTable.destroy();
      this.overviewTable = void 0;
    }
    this.table = void 0;
    this.dtBulk = void 0;
    const contentsEl = this.dom;
    contentsEl.innerHTML = "";
    const hiddenCols = [0];
    if (window.innerWidth < 500) {
      hiddenCols.push(1);
      if (window.innerWidth < 450) {
        hiddenCols.push(3);
      }
    }
    this.overviewTable = new OverviewDataTable({
      dom: contentsEl,
      classes: ["fw-data-table", "fw-large"],
      columns: [
        {
          select: 0,
          type: "number"
        },
        {
          select: 1,
          type: "boolean",
          sortable: false
        },
        {
          select: hiddenCols,
          hidden: true
        },
        {
          select: 6,
          sortable: false
        },
        {
          select: [this.lastSort.column],
          sort: this.lastSort.dir
        }
      ],
      data: ids.map((id) => this.createTableRow(id)),
      idColumn: 0,
      checkboxColumn: 1,
      bulkMenu: bulkMenuModel(),
      bulkMenuPage: this,
      searchable: true,
      scrollY: `${Math.max(window.innerHeight - 360, 100)}px`,
      tabIndex: 1,
      labels: {
        noRows: gettext("No sources registered"),
        noResults: gettext("No sources found")
        // Message shown when there are no search results
      },
      headings: [
        "",
        "",
        gettext("Title"),
        gettext("Sourcetype"),
        gettext("Author"),
        gettext("Published"),
        ""
      ],
      template: (options, _dom) => `<div class='${options.classes.container}'${options.scrollY.length ? ` style='height: ${options.scrollY}; overflow-Y: auto;'` : ""}></div>`,
      rowRender: (row, tr2, _index) => {
        const id = row.cells[0].data;
        const inputNode = {
          nodeName: "input",
          attributes: {
            type: "checkbox",
            class: "entry-select fw-check",
            "data-id": id,
            id: `bib-${id}`
          }
        };
        if (row.cells[1].data) {
          inputNode.attributes.checked = true;
        }
        ;
        tr2.childNodes[0].childNodes = [
          inputNode,
          {
            nodeName: "label",
            attributes: {
              for: `bib-${id}`
            }
          }
        ];
      },
      onEnter: (row, _event) => {
        if (this.getSelected().length > 0) {
          return;
        }
        const rowIndex = this.table.data.data.indexOf(row);
        const editButton = this.table.dom.querySelector(
          `tr[data-index="${rowIndex}"] span.edit-bib`
        );
        if (editButton) {
          ;
          editButton.click();
        }
      },
      onDelete: (row) => {
        const bibId = row.cells[0].data;
        this.deleteBibEntryDialog([bibId]);
      }
    });
    this.overviewTable.init();
    this.table = this.overviewTable.table;
    this.table.id = "bibliography";
    this.dtBulk = this.overviewTable.dtBulk;
    this.table.on("datatable.sort", (column, dir) => {
      this.lastSort = { column, dir };
    });
    this.table.dom.focus();
  }
  /** Adds a list of bibliography categories to current list of bibliography categories.
   * @function setBibCategoryList
   * @param newBibCategories The new categories which will be added to the existing ones.
   */
  setBibCategoryList(bibCategories) {
    const catSelector = this.menu.model.content.find(
      (menuItem) => menuItem.id === "cat_selector"
    );
    if (!catSelector) {
      return;
    }
    const dropdown = catSelector;
    dropdown.content = dropdown.content.filter((cat) => cat.type !== "category");
    dropdown.content = dropdown.content.concat(
      bibCategories.map((cat) => ({
        title: cat.category_title,
        type: "category",
        action: (_overview) => {
          const trs = this.dom.querySelectorAll(
            "#bibliography > tbody > tr"
          );
          trs.forEach((tr2) => {
            const titleEl = tr2.querySelector(".fw-data-table-title");
            if (titleEl && titleEl.classList.contains(`cat_${cat.id}`)) {
              ;
              tr2.style.display = "";
            } else {
              ;
              tr2.style.display = "none";
            }
          });
        }
      }))
    );
    this.menu.update();
  }
  /** This takes a list of new bib entries and adds them to BibDB and the bibliography table
   * @function updateTable
   */
  updateTable(ids) {
    this.removeTableRows(ids);
    this.table.insert({ data: ids.map((id) => this.createTableRow(id)) });
    this.table.columns.sort(this.lastSort.column, this.lastSort.dir);
  }
  createTableRow(id) {
    const bibInfo = this.app.bibDB.db[id];
    const bibauthors = bibInfo.fields.author || bibInfo.fields.editor;
    const cats = bibInfo.cats.map((cat) => `cat_${cat}`);
    return [
      id,
      false,
      // checkbox
      `<span class="fw-data-table-title ${cats.join(" ")}">
                <i class="fa fa-book"></i>
                <span class="edit-bib fw-link-text fw-searchable" data-id="${id}">
                    ${bibInfo.fields.title?.length ? escapeText(litToText(bibInfo.fields.title)) : gettext("Untitled")}
                </span>
                ${bibInfo.entry_key ? `<small class="bib-entry-key">${escapeText(bibInfo.entry_key)}</small>` : ""}
            </span>`,
      // title
      getBibTypeTitle(bibInfo.bib_type),
      // sourcetype
      bibauthors ? nameToText(bibauthors) : "",
      // author
      `<span class="fw-date">${bibInfo.fields.date ? bibInfo.fields.date.replace("/", " ") : ""}</span>`,
      // published,
      `<span class="delete-bib fw-link-text" data-id="${id}"><i class="fa fa-trash-alt">  </i></span>`
      // delete icon
    ];
  }
  removeTableRows(ids) {
    const existingRows = this.table.data.data.map((row, index) => {
      const id = row.cells[0].data;
      if (ids.includes(id)) {
        return index;
      } else {
        return false;
      }
    }).filter((rowIndex) => rowIndex !== false);
    if (existingRows.length) {
      this.table.rows.remove(existingRows);
    }
  }
  /** Opens a dialog for editing categories.
   * @function editCategoriesDialog
   */
  editCategoriesDialog() {
    if (this.app.isOffline()) {
      addAlert(
        "info",
        gettext(
          "You are currently offline. Please try again when you are back online."
        )
      );
      return;
    }
    const buttons = [
      {
        text: gettext("Submit"),
        classes: "fw-dark",
        click: () => {
          const cats = {
            ids: [],
            titles: []
          };
          document.querySelectorAll("#edit-categories .category-form").forEach((el) => {
            const title = el.value.trim();
            if (title.length) {
              cats.ids.push(
                Number.parseInt(
                  el.getAttribute("data-id") || "0"
                )
              );
              cats.titles.push(title);
            }
          });
          if (this.app.isOffline()) {
            addAlert(
              "info",
              gettext(
                "You are currently offline. Please try again when you are back online."
              )
            );
          } else {
            this.saveCategories(cats);
          }
          dialog.close();
        }
      },
      {
        type: "cancel"
      }
    ];
    const dialog = new Dialog({
      id: "edit-categories",
      width: 420,
      height: 350,
      title: gettext("Edit Categories"),
      body: editCategoriesTemplate({
        categories: this.app.bibDB.cats
      }),
      buttons
    });
    dialog.open();
  }
  /** Dialog to confirm deletion of bibliography items.
   * @function deleteBibEntryDialog
   * @param ids Ids of items that are to be deleted.
   */
  deleteBibEntryDialog(ids) {
    const buttons = [
      {
        text: gettext("Delete"),
        classes: "fw-dark",
        click: () => {
          this.deleteBibEntries(ids);
          dialog.close();
        }
      },
      {
        type: "cancel"
      }
    ];
    const dialog = new Dialog({
      id: "confirmdeletion",
      title: gettext("Confirm deletion"),
      body: `<p>${gettext("Delete the bibliography item(s)")}?</p>`,
      buttons,
      icon: "exclamation-triangle"
    });
    dialog.open();
  }
  // get IDs of selected bib entries
  getSelected() {
    return Array.from(
      this.dom.querySelectorAll(".entry-select:checked:not(:disabled)")
    ).map((el) => Number.parseInt(el.getAttribute("data-id") || ""));
  }
  activatePlugins() {
    if (this.plugins) {
      return;
    }
    this.plugins = {};
    return Promise.all(
      this.bibPlugins.map(([app2, plugin]) => {
        if (!this.app.settings.APPS.includes(app2)) {
          return Promise.resolve();
        }
        return Promise.all(
          Object.values(plugin).map((pluginExport) => {
            if (typeof pluginExport === "function") {
              this.plugins[pluginExport.name] = new pluginExport(
                this
              );
              return this.plugins[pluginExport.name].init() || Promise.resolve();
            }
            return Promise.resolve();
          })
        );
      })
    );
  }
  /** Initialize the bibliography table and bind interactive parts.
   * @function bibEvents
   */
  bindEvents() {
    this._boundHandleActivation = (event) => this.handleActivation(event);
    document.body.addEventListener("click", this._boundHandleActivation);
    document.body.addEventListener("keydown", this._boundHandleActivation);
    this.dom.addEventListener("paste", (event) => {
      if (event.target.nodeName === "INPUT") {
        return false;
      }
      if (!event.clipboardData) {
        return false;
      }
      const text2 = event.clipboardData.getData("text");
      return this.getBibtex(text2);
    });
    this.dom.addEventListener("dragover", (event) => {
      if (event.dataTransfer && event.dataTransfer.types.includes("text/plain")) {
        event.preventDefault();
      }
    });
    this.dom.addEventListener("dragenter", (event) => {
      if (event.dataTransfer && event.dataTransfer.types.includes("text/plain")) {
        event.preventDefault();
      }
    });
    this.dom.addEventListener("drop", (event) => {
      if (event.target.nodeName === "INPUT") {
        return false;
      }
      if (!event.dataTransfer) {
        return false;
      }
      const text2 = fixUtf8(event.dataTransfer.getData("text"));
      return this.getBibtex(text2);
    });
  }
  handleActivation(event) {
    if (!isActivationEvent(event)) {
      return;
    }
    const el = {};
    switch (true) {
      case findTarget(event, ".delete-bib", el): {
        const bibId = Number.parseInt(
          el.target.dataset.id || ""
        );
        this.deleteBibEntryDialog([bibId]);
        break;
      }
      case findTarget(event, ".edit-bib", el): {
        const bibId = Number.parseInt(
          el.target.dataset.id || ""
        );
        Promise.resolve().then(() => (init_form(), form_exports)).then(({ BibEntryForm: BibEntryForm2 }) => {
          const form = new BibEntryForm2(
            this.app.bibDB,
            this.app,
            bibId
          );
          form.init().then((idTranslations) => {
            if (!idTranslations) {
              return;
            }
            const ids = idTranslations.map((idTrans) => idTrans[1]);
            return this.updateTable(ids);
          });
        });
        break;
      }
      case findTarget(event, ".fw-add-input", el): {
        const itemEl = el.target.closest(".fw-list-input");
        if (!itemEl) {
          break;
        }
        if (!itemEl.nextElementSibling) {
          itemEl.insertAdjacentHTML(
            "afterend",
            `<tr class="fw-list-input">
                            <td>
                                <input type="text" class="category-form">
                                <span class="fw-add-input icon-addremove" tabindex="0"></span>
                            </td>
                        </tr>`
          );
        } else {
          itemEl.parentElement.removeChild(itemEl);
        }
        break;
      }
      case (event.type === "keydown" && event.target.matches(".category-form")): {
        const input = event.target;
        if (!input.value.trim().length) {
          break;
        }
        const itemEl = input.closest(
          ".fw-list-input"
        );
        if (!itemEl?.nextElementSibling) {
          itemEl?.insertAdjacentHTML(
            "afterend",
            `<tr class="fw-list-input">
                            <td>
                                <input type="text" class="category-form">
                                <span class="fw-add-input icon-addremove" tabindex="0"></span>
                            </td>
                        </tr>`
          );
          const newInput = itemEl?.nextElementSibling?.querySelector(
            ".category-form"
          );
          newInput?.focus();
        }
        break;
      }
      default:
        break;
    }
  }
  // find bibtex in pasted or dropped data.
  getBibtex(text2) {
    Promise.resolve().then(() => (init_import(), import_exports)).then(({ BibliographyImporter: BibliographyImporter2 }) => {
      const importer = new BibliographyImporter2(
        text2,
        this.app.bibDB,
        (newIds) => this.updateTable(newIds),
        false
      );
      importer.init();
    });
    return true;
  }
  saveCategories(cats) {
    this.app.bibDB.saveCategories(cats).then((bibCats) => this.setBibCategoryList(bibCats));
  }
  deleteBibEntries(ids) {
    this.app.bibDB.deleteBibEntries(ids).then((ids2) => this.removeTableRows(ids2));
  }
  close() {
    if (this.table) {
      this.table.destroy();
      this.table = void 0;
    }
    if (this.dtBulk) {
      this.dtBulk.destroy();
      this.dtBulk = void 0;
    }
    if (this.menu) {
      this.menu.destroy();
      this.menu = void 0;
    }
    if (this._boundHandleActivation) {
      document.body.removeEventListener(
        "click",
        this._boundHandleActivation
      );
      document.body.removeEventListener(
        "keydown",
        this._boundHandleActivation
      );
      this._boundHandleActivation = void 0;
    }
  }
};

