// demo/mock/mock-db.ts
var MockBibDB = class {
  db;
  cats;
  nextId;
  constructor() {
    this.db = {};
    this.cats = [];
    this.nextId = 1;
  }
  /** Add a bibliography entry programmatically (not part of BibDBCollection). */
  addEntry(entry) {
    const id = this.nextId++;
    this.db[id] = { ...entry, id };
    return id;
  }
  async saveBibEntries(tmpDB, isNew) {
    const translations = [];
    for (const [tmpId, entry] of Object.entries(tmpDB)) {
      const numTmpId = Number(tmpId);
      if (isNew) {
        const newId = this.nextId++;
        this.db[newId] = { ...entry, id: newId };
        translations.push([numTmpId, newId]);
      } else {
        this.db[numTmpId] = { ...entry, id: numTmpId };
        translations.push([numTmpId, numTmpId]);
      }
    }
    return translations;
  }
  async saveCategories(cats) {
    for (let i3 = 0; i3 < cats.ids.length; i3++) {
      const id = cats.ids[i3];
      const title = cats.titles[i3];
      if (id) {
        const existing = this.cats.find((c2) => c2.id === id);
        if (existing) {
          existing.category_title = title;
        }
      } else {
        this.cats.push({
          id: Math.max(0, ...this.cats.map((c2) => c2.id)) + 1,
          category_title: title
        });
      }
    }
    return [...this.cats];
  }
  async deleteBibEntries(ids) {
    const deleted = [];
    for (const id of ids) {
      if (id in this.db) {
        delete this.db[id];
        deleted.push(id);
      }
    }
    return deleted;
  }
};

